<?php
require_once __DIR__ . '/../core/JalaliDate.php';require_once __DIR__ . '/../core/Auth.php';require_once __DIR__ . '/../core/Database.php';require_once __DIR__ . '/../core/Response.php';require_once __DIR__ . '/../lib/OrgAccess.php';
Auth::requirePermission('hr_kpi.results');$pageTitle='نتایج ارزیابی KPI';$user=Auth::user();[$scopeSql,$scopeParams]=OrgAccess::scopeSql($user,'u.id');$where=[$scopeSql];$params=$scopeParams;
function kpi_safe_row($value): array { return is_array($value) ? $value : []; }
function kpi_safe_value($value, string $default='-'): string { return $value === null || $value === '' ? $default : (string)$value; }
foreach(['employee_id'=>'s.employee_id','period_id'=>'s.period_id','template_id'=>'s.template_id','org_unit_id'=>'u.org_unit_id','org_role_id'=>'u.org_role_id','scored_by'=>'s.scored_by','parent_user_id'=>'u.parent_user_id'] as $key=>$column){$value=(int)($_GET[$key]??0);if($value){$where[]="{$column}=?";$params[]=$value;}}
if(trim((string)($_GET['status']??''))!==''){$status=$_GET['status'];if($status==='needs_followup')$where[]='s.score/c.max_score*100<60';elseif($status==='good')$where[]='s.score/c.max_score*100>=75';}
foreach(['from_date'=>'>=','to_date'=>'<='] as $key=>$op){$value=trim((string)($_GET[$key]??''));if($value!==''){$where[]="DATE(s.scored_at){$op}?";$params[]=JalaliDate::toGregorian($value)?:$value;}}
$sql='SELECT s.employee_id,COALESCE(NULLIF(u.name,""),NULLIF(u.username,""),"کاربر نامشخص") name,COALESCE(NULLIF(ou.title,""),NULLIF(u.department,""),"-") unit_title,COALESCE(NULLIF(orr.title,""),NULLIF(u.role_key,""),"-") role_title,COALESCE(u.sales_line,"-") sales_line,COALESCE(NULLIF(puser.name,""),NULLIF(puser.username,""),"-") parent_name,COALESCE(NULLIF(t.title,""),"-") template_title,s.template_id,COALESCE(NULLIF(p.title,""),"-") period_title,s.period_id,ROUND(SUM(COALESCE(s.score,0)*COALESCE(c.weight,1)),2) total_score,ROUND(SUM(COALESCE(s.score,0)*COALESCE(c.weight,1))/NULLIF(SUM(COALESCE(c.max_score,0)*COALESCE(c.weight,1)),0)*100,2) average_score,MAX(s.scored_at) scored_at,MAX(s.updated_at) updated_at,COALESCE(MAX(NULLIF(sc.name,"")),MAX(NULLIF(sc.username,"")),"-") scored_by_name,MAX(s.scored_by) scored_by_id FROM hr_kpi_scores s LEFT JOIN users u ON u.id=s.employee_id LEFT JOIN hr_kpi_templates t ON t.id=s.template_id LEFT JOIN hr_kpi_periods p ON p.id=s.period_id LEFT JOIN hr_kpi_criteria c ON c.id=s.criteria_id LEFT JOIN org_units ou ON ou.id=u.org_unit_id LEFT JOIN org_roles orr ON orr.id=u.org_role_id LEFT JOIN users puser ON puser.id=COALESCE(u.parent_user_id,u.supervisor_id,u.organization_manager_id) LEFT JOIN users sc ON sc.id=s.scored_by WHERE '.implode(' AND ',$where).' GROUP BY s.employee_id,s.template_id,s.period_id,u.name,u.username,ou.title,u.department,orr.title,u.role_key,u.sales_line,puser.name,puser.username,t.title,p.title ORDER BY MAX(p.sort_order) DESC,average_score DESC';
try{$results=Database::fetchAll($sql,$params);}catch(Throwable $e){error_log('HR KPI results query: '.$e->getMessage());$results=[];flash('دریافت نتایج KPI با خطا مواجه شد. لطفاً دوباره تلاش کنید.','danger');}
foreach($results as &$result){$result=array_replace(['employee_id'=>0,'template_id'=>0,'period_id'=>0,'name'=>'کاربر نامشخص','unit_title'=>'-','role_title'=>'-','sales_line'=>'-','parent_name'=>'-','template_title'=>'-','period_title'=>'-','total_score'=>0,'average_score'=>0,'scored_at'=>null,'updated_at'=>null,'scored_by_name'=>'-'],kpi_safe_row($result));try{$criteriaRows=Database::fetchAll('SELECT COALESCE(NULLIF(c.criteria_text,""),"-") criteria_text,COALESCE(s.score,0) score,COALESCE(c.max_score,0) max_score,COALESCE(NULLIF(s.notes,""),"-") notes,s.updated_at FROM hr_kpi_scores s LEFT JOIN hr_kpi_criteria c ON c.id=s.criteria_id WHERE s.employee_id=? AND s.template_id=? AND s.period_id=? ORDER BY c.sort_order,c.id',[(int)$result['employee_id'],(int)$result['template_id'],(int)$result['period_id']]);$result['criteria']=array_values(array_filter(array_map('kpi_safe_row',$criteriaRows)));}catch(Throwable $e){error_log('HR KPI result criteria: '.$e->getMessage());$result['criteria']=[];}$score=$result['average_score'];$result['average_score']=$score===null?0:(float)$score;$result['status']=$score===null?'نامشخص':((float)$score>=75?'خوب':((float)$score>=60?'پایدار':'نیازمند پیگیری'));}unset($result);
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="hr-kpi-results.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['نام کاربر','واحد سازمانی','نقش سازمانی','مدیر مستقیم','لاین فروش','قالب','دوره','ثبت‌کننده','امتیاز','وضعیت','تاریخ ثبت','آخرین ویرایش']);foreach($results as $row)fputcsv($out,[$row['name'],$row['unit_title'],$row['role_title'],$row['parent_name'],$row['sales_line'],$row['template_title'],$row['period_title'],$row['scored_by_name'],$row['average_score'],$row['status'],$row['scored_at'],$row['updated_at']]);fclose($out);exit;}
$accessibleIds=OrgAccess::accessibleUserIds($user);if(!$accessibleIds)$accessibleIds=[-1];$employees=Database::fetchAll('SELECT id,name FROM users WHERE id IN ('.implode(',',array_fill(0,count($accessibleIds),'?')).') ORDER BY name',$accessibleIds);$units=Database::fetchAll('SELECT id,title FROM org_units WHERE active=1 ORDER BY sort_order,title');$roles=Database::fetchAll('SELECT id,title FROM org_roles WHERE active=1 ORDER BY sort_order,title');$templates=Database::fetchAll('SELECT id,title FROM hr_kpi_templates ORDER BY title');$periods=Database::fetchAll('SELECT id,title FROM hr_kpi_periods ORDER BY sort_order');$scorers=Database::fetchAll('SELECT DISTINCT u.id,u.name FROM users u JOIN hr_kpi_scores s ON s.scored_by=u.id ORDER BY u.name');$parents=Database::fetchAll('SELECT id,name FROM users WHERE id IN ('.implode(',',array_fill(0,count($accessibleIds),'?')).') ORDER BY name',$accessibleIds);
require __DIR__ . '/../views/partials/admin-header.php';
?>
<form class="card admin-form" method="get"><h2>فیلتر نتایج KPI</h2><div class="grid grid-3"><?php $selects=[['employee_id','کاربر ارزیابی‌شونده',$employees],['org_unit_id','واحد سازمانی',$units],['org_role_id','نقش سازمانی',$roles],['scored_by','ثبت‌کننده',$scorers],['parent_user_id','مدیر مستقیم',$parents],['template_id','قالب KPI',$templates],['period_id','دوره',$periods]];foreach($selects as [$name,$label,$items]):?><label class="form-field"><span><?=e($label)?></span><select name="<?=e($name)?>"><option value="">همه</option><?php foreach($items as $item):?><option value="<?=$item['id']?>" <?=(int)($_GET[$name]??0)===(int)$item['id']?'selected':''?>><?=e($item['title']??$item['name'])?></option><?php endforeach?></select></label><?php endforeach?><label class="form-field"><span>از تاریخ</span><input class="jalali-date-input" name="from_date" value="<?=e($_GET['from_date']??'')?>"></label><label class="form-field"><span>تا تاریخ</span><input class="jalali-date-input" name="to_date" value="<?=e($_GET['to_date']??'')?>"></label><label class="form-field"><span>وضعیت</span><select name="status"><option value="">همه</option><option value="good" <?=($_GET['status']??'')==='good'?'selected':''?>>خوب</option><option value="needs_followup" <?=($_GET['status']??'')==='needs_followup'?'selected':''?>>نیازمند پیگیری</option></select></label></div><div class="form-actions"><button class="btn btn-primary">اعمال فیلتر</button><button class="btn" name="export" value="csv">خروجی CSV</button><a class="btn" href="/admin/hr-kpi-results.php">پاکسازی</a></div></form>
<section class="card"><div class="table-wrap"><table><thead><tr><th>کاربر</th><th>واحد / نقش</th><th>مدیر مستقیم</th><th>دوره</th><th>ثبت‌کننده</th><th>امتیاز</th><th>وضعیت</th><th>تاریخ</th><th>جزئیات</th></tr></thead><tbody><?php foreach($results as $row):?><tr><td><?=e($row['name'])?></td><td><?=e($row['unit_title'].' / '.$row['role_title'])?></td><td><?=e($row['parent_name']?:'-')?></td><td><?=e($row['period_title'])?></td><td><?=e($row['scored_by_name']?:'-')?></td><td><?=e($row['average_score'])?>٪</td><td><span class="achievement-pill <?=((float)$row['average_score']>=75?'achievement-good':((float)$row['average_score']>=60?'achievement-warn':'achievement-bad'))?>"><?=e($row['status'])?></span></td><td><?=e($row['scored_at']?format_jalali_datetime($row['scored_at']):'-')?></td><td><details class="kpi-detail"><summary>مشاهده کامل</summary><dl><div><dt>قالب</dt><dd><?=e($row['template_title'])?></dd></div><div><dt>جمع امتیاز</dt><dd><?=e($row['total_score'])?></dd></div><div><dt>میانگین</dt><dd><?=e($row['average_score'])?>٪</dd></div><div><dt>آخرین ویرایش</dt><dd><?=e($row['updated_at']?format_jalali_datetime($row['updated_at']):'-')?></dd></div></dl><div class="table-wrap"><table><thead><tr><th>معیار</th><th>امتیاز</th><th>توضیحات</th></tr></thead><tbody><?php foreach($row['criteria'] as $criterion):?><tr><td><?=e($criterion['criteria_text'])?></td><td><?=e($criterion['score'])?> / <?=e($criterion['max_score'])?></td><td><?=e($criterion['notes']?:'-')?></td></tr><?php endforeach?></tbody></table></div><button class="btn btn-small" type="button" onclick="window.print()">چاپ</button></details></td></tr><?php endforeach?><?php if(!$results):?><tr><td colspan="9">نتیجه‌ای یافت نشد.</td></tr><?php endif?></tbody></table></div></section>
<?php require __DIR__ . '/../views/partials/admin-footer.php'; ?>
